theme_overrides:
/* ============================================================
   theme "Editorial Brief" — skill2web frontend-design pass (v0.3)
   refined internal-memo aesthetic · CSS-only · zero remote deps
   ============================================================ */
:root{
  --paper:#F4F0E6; --paper-deep:#ECE6D7; --card:#FFFDF8;
  --ink:#211C15; --ink-soft:#5A5246; --ink-faint:#8E8676;
  --clay:#A8442B; --clay-deep:#84321F; --clay-tint:#F0E3DC;
  --hair:#E2DAC8; --gold:#9A7B3C;
  --font-display:"Iowan Old Style","Palatino Linotype",Palatino,"Book Antiqua",Georgia,"Songti SC",serif;
  --font-body:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei","Helvetica Neue",Arial,sans-serif;
  --shadow:0 1px 2px rgba(33,28,21,.04),0 8px 24px -12px rgba(33,28,21,.14);
}
body{
  background:linear-gradient(180deg,var(--paper) 0%,var(--paper-deep) 100%) fixed;
  color:var(--ink); font-family:var(--font-body); -webkit-font-smoothing:antialiased;
}
header{
  background:transparent; border-bottom:1px solid var(--hair);
  padding:30px 40px 22px; box-shadow:inset 0 3px 0 var(--clay);
}
header h1{
  font-family:var(--font-display); font-weight:600; font-size:27px;
  letter-spacing:-.015em; color:var(--ink);
}
header h1::before{content:"\00A7 ";color:var(--clay);font-weight:400}
header .subtitle{color:var(--ink-faint);font-size:11.5px;letter-spacing:.02em;margin-top:6px}
header .subtitle a{color:var(--ink-soft);border-bottom:1px solid var(--hair)}
.btn-settings{
  border:1px solid var(--ink); color:var(--ink); background:transparent;
  border-radius:0; letter-spacing:.08em; text-transform:uppercase;
  font-size:10.5px; padding:8px 16px; transition:background .18s,color .18s;
}
.btn-settings:hover{background:var(--ink);color:var(--paper)}
main{max-width:880px;padding:36px 40px 80px}
section{
  background:var(--card); border:1px solid var(--hair); border-radius:3px;
  padding:30px 34px; margin-bottom:22px; box-shadow:var(--shadow);
  animation:rise .5s cubic-bezier(.2,.7,.2,1) both;
}
section:nth-of-type(2){animation-delay:.05s}
section:nth-of-type(3){animation-delay:.1s}
section:nth-of-type(4){animation-delay:.15s}
@keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
section h2{
  font-family:var(--font-display); font-size:18px; font-weight:600;
  letter-spacing:-.01em; padding-bottom:14px; margin-bottom:18px;
  border-bottom:1px solid var(--hair);
}
section h2 .step-num{
  width:25px; height:25px; background:var(--clay); color:var(--paper);
  border-radius:50%; font-family:var(--font-body); font-size:12px;
  font-weight:600; line-height:25px;
}
.form-row label{
  text-transform:uppercase; letter-spacing:.09em; font-size:10.5px;
  color:var(--ink-faint); font-weight:600;
}
.form-row input[type="text"],.form-row input[type="password"],
.form-row input[type="number"],.form-row textarea,.form-row select{
  background:var(--paper); border:1px solid var(--hair); border-radius:3px;
  color:var(--ink); padding:10px 13px;
  transition:border-color .16s,box-shadow .16s,background .16s;
}
.form-row input:focus,.form-row textarea:focus,.form-row select:focus{
  border-color:var(--clay); background:var(--card);
  box-shadow:0 0 0 3px var(--clay-tint);
}
.form-row textarea{min-height:150px;line-height:1.6}
.btn-primary{
  background:var(--clay); color:#FFF8F1; border-radius:3px; font-weight:600;
  letter-spacing:.02em; padding:11px 26px; box-shadow:0 2px 0 var(--clay-deep);
  transition:transform .12s,box-shadow .12s,background .16s;
}
.btn-primary:hover{background:var(--clay-deep);transform:translateY(-1px);box-shadow:0 3px 0 var(--clay-deep)}
.btn-primary:active{transform:translateY(1px);box-shadow:0 1px 0 var(--clay-deep)}
.btn-primary:disabled{background:var(--ink-faint);box-shadow:none;color:var(--paper)}
.btn-secondary{
  background:transparent; border:1px solid var(--ink-soft);
  color:var(--ink-soft); border-radius:3px;
}
.btn-secondary:hover{background:var(--paper-deep);color:var(--ink)}
#settings-panel{
  background:linear-gradient(180deg,#FBF6E9,#F6EFDD); border:1px solid #E6D7AE;
}
#settings-panel h2{border-bottom-color:#E6D7AE}
#settings-panel h2 .step-num{background:var(--gold);color:#FFF}
.progress-step.running .indicator{background:var(--clay)}
.progress-step.done .indicator{background:var(--gold)}
.progress-step.skip .indicator{background:var(--hair);color:var(--ink-faint)}
.progress-step.running{color:var(--ink)}
#article h1,#article h2,#article h3{font-family:var(--font-display);letter-spacing:-.01em}
#article h1{color:var(--clay-deep)}
footer{border-top:1px solid var(--hair);color:var(--ink-faint);background:transparent}
footer a{color:var(--ink-soft)}
